"""Client that posts records to the ingestion API."""
import json
import os
import urllib.error
import urllib.request

# The ingestion endpoint is provided by the runtime environment, not stored here.
ENDPOINT = os.environ.get("INGESTION_ENDPOINT", "").rstrip("/")


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status in (200, 201, 202):
                    accepted += 1
        except urllib.error.HTTPError:
            # A non-2xx response means this record was not accepted; keep
            # sending the remaining records.
            continue
        except Exception:
            # Do not let one failed request stop the rest of the batch.
            continue
    return accepted


def main():
    if not ENDPOINT:
        raise SystemExit(
            "INGESTION_ENDPOINT is not set; provide the ingestion API URL "
            "before running sync.py"
        )
    records = load_records()
    accepted = post_records(ENDPOINT, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()
